window.TRILHA_GOLD_BANKS=window.TRILHA_GOLD_BANKS||{};window.TRILHA_GOLD_BANKS["v5-sc-A4"]={"id":"sc-A4","title":"Meningite | 30 casos clínicos originais","group":"P2 • Saúde da Criança II","source":"Biblioteca da Trilha de Ouro SDCII A4; questões autorais de treino clínico, não questões oficiais","version":"5.1.0","questions":[{"id":"ouro-rigor5-sc-A4-01","topicId":"sc-A4","stem":"Lactente de 5 semanas chega com febre de 38,7 °C, recusa alimentar, irritabilidade ao manuseio e episódios de hipoatividade. Está hemodinamicamente estável, sem rigidez nucal e com fontanela normotensa. A mãe pergunta se a ausência de sinais meníngeos afasta meningite. Qual é a interpretação que melhor orienta a investigação?","options":["O exame neurológico sem rigidez torna meningite bacteriana suficientemente improvável para dispensar investigação.","A fontanela normotensa é teste de exclusão de infecção do sistema nervoso central.","Investigar infecção invasiva, inclusive meningite, apesar dos sinais meníngeos ausentes.","A estabilidade pressórica basta para afastar doença bacteriana invasiva.","A irritabilidade só tem relevância se ocorrer simultaneamente a convulsão."],"answer":2,"analysis":["INCORRETA. Sinais clássicos podem faltar nessa faixa etária.","INCORRETA. Abaulamento não é obrigatório e sua ausência não exclui meningite.","CORRETA. Em lactentes jovens, sinais meníngeos clássicos têm sensibilidade limitada; história, exame seriado e investigação de infecção bacteriana grave importam.","INCORRETA. Infecção invasiva pode estar presente antes de hipotensão.","INCORRETA. Alteração de alimentação e comportamento já pode ser sinal relevante em lactentes."],"explanation":"Em lactentes jovens, sinais meníngeos clássicos têm sensibilidade limitada; história, exame seriado e investigação de infecção bacteriana grave importam.","memorizar":"LACTENTE FEBRIL + MUDANÇA DE COMPORTAMENTO: ausência de rigidez não exclui meningite.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"apresentação em lactentes","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"difícil"},{"id":"ouro-rigor5-sc-A4-02","topicId":"sc-A4","stem":"Menino de 8 anos tem febre há 10 horas, extremidades frias, enchimento capilar de 6 segundos, sonolência, petéquias que aumentam e pressão arterial em queda. Um profissional propõe punção lombar imediata antes de qualquer outra medida. Qual conduta tem a melhor relação de prioridade e segurança?","options":["Realizar punção imediatamente porque petéquias indicam necessariamente meningite com pressão intracraniana normal.","Solicitar TC de crânio e só iniciar antimicrobiano depois do laudo.","Priorizar isolamento e aguardar cultura antes de administrar tratamento.","Esperar aparecimento de rigidez de nuca antes de tratar como infecção invasiva.","Estabilizar choque e iniciar antibiótico; adiar punção lombar."],"answer":4,"analysis":["INCORRETA. Petéquias podem acompanhar meningococcemia e choque; instabilidade torna punção insegura.","INCORRETA. Imagem não deve retardar terapia em doença bacteriana grave.","INCORRETA. Isolamento é relevante, mas a demora no tratamento de sepse grave é perigosa.","INCORRETA. Meningococcemia pode ocorrer sem síndrome meníngea clássica.","CORRETA. Purpura/petéquias progressivas com choque sugerem doença meningocócica invasiva e instabilidade; punção não precede ressuscitação nem antibiótico."],"explanation":"Purpura/petéquias progressivas com choque sugerem doença meningocócica invasiva e instabilidade; punção não precede ressuscitação nem antibiótico.","memorizar":"PETÉQUIAS PROGRESSIVAS + HIPOPERFUSÃO: pense em MENINGOCOCCEMIA, trate primeiro.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"meningococcemia e prioridade","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A4-03","topicId":"sc-A4","stem":"Menina de 7 anos com febre, cefaleia e rigidez de nuca está alerta, estável, sem déficit focal, sem convulsões e sem sinais de hipertensão intracraniana. Antimicrobianos estão sendo preparados. Um colega recomenda TC em todos os casos antes da punção. Qual proposta é mais defensável?","options":["Fazer TC obrigatória porque qualquer rigidez nucal significa edema cerebral difuso.","Puncionar se seguro, sem TC rotineira e sem atrasar tratamento.","Iniciar tratamento apenas após confirmação microbiológica no líquor.","Dispensar líquor porque uma criança alerta não pode ter meningite bacteriana.","Solicitar somente hemograma, pois a punção não contribui quando existe febre."],"answer":1,"analysis":["INCORRETA. Rigidez nucal por si só não exige neuroimagem.","CORRETA. Neuroimagem prévia universal não melhora segurança em criança estável sem critérios de risco e pode atrasar diagnóstico e terapia.","INCORRETA. Suspeita de meningite bacteriana exige conduta oportuna.","INCORRETA. Estado de consciência preservado não exclui meningite.","INCORRETA. Quando segura, a análise do líquor é central para diagnóstico e etiologia."],"explanation":"Neuroimagem prévia universal não melhora segurança em criança estável sem critérios de risco e pode atrasar diagnóstico e terapia.","memorizar":"TC antes da punção não é rotina: usar sinais clínicos de risco.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"punção lombar sem TC rotineira","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"difícil"},{"id":"ouro-rigor5-sc-A4-04","topicId":"sc-A4","stem":"Adolescente de 12 anos apresenta febre alta, cefaleia progressiva, desorientação e nova paresia braquial direita. A equipe suspeita de infecção do SNC, mas há sinais de possível lesão intracraniana com efeito de massa. O que modifica corretamente a sequência assistencial?","options":["Adiar punção e iniciar terapia enquanto investiga déficit focal.","Puncionar imediatamente para medir a pressão de abertura antes de qualquer terapêutica.","Aguardar a TC para então colher culturas e só depois começar antimicrobianos.","Descartar meningite porque fraqueza focal é incompatível com infecção.","Tratar apenas como enxaqueca porque não existe informação de rigidez nucal."],"answer":0,"analysis":["CORRETA. Déficit focal e deterioração do estado mental elevam risco de lesão expansiva ou hipertensão intracraniana e mudam a segurança da punção.","INCORRETA. Punção com sinais neurológicos de risco pode ser perigosa.","INCORRETA. A investigação não deve retardar tratamento de suspeita bacteriana grave.","INCORRETA. Infecções do SNC podem produzir complicações focais.","INCORRETA. Febre e déficit focal não são explicados de forma segura por cefaleia primária."],"explanation":"Déficit focal e deterioração do estado mental elevam risco de lesão expansiva ou hipertensão intracraniana e mudam a segurança da punção.","memorizar":"DÉFICIT FOCAL OU CONSCIÊNCIA COMPROMETIDA: reavaliar segurança da punção.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"contraindicação à punção","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A4-05","topicId":"sc-A4","stem":"Criança de 6 anos com febre e rebaixamento leve tem líquor turvo: 2.400 leucócitos/mm³, 90% neutrófilos, proteína 230 mg/dL e glicose liquórica 18 mg/dL com glicemia sérica 102 mg/dL. Qual hipótese é mais sustentada pela combinação, antes da cultura?","options":["Meningite viral típica, porque neutrófilos são específicos de enterovírus.","Hemorragia subaracnóidea isolada, porque glicose baixa confirma presença de sangue.","Líquor normal para a idade, porque 2.400 células/mm³ pode ocorrer após febre.","Padrão liquórico fortemente sugestivo de meningite bacteriana.","Meningite fúngica definida pela neutrofilia, sem necessidade de contextualização."],"answer":3,"analysis":["INCORRETA. Neutrófilos iniciais podem ocorrer em viroses, mas hipoglicorraquia marcante e proteína elevada pesam contra padrão viral típico.","INCORRETA. A composição celular/inflamatória é mais compatível com infecção, e glicose baixa não confirma hemorragia.","INCORRETA. Essa celularidade e perfil bioquímico são claramente patológicos.","CORRETA. O padrão integrado de pleocitose intensa, neutrófilos, relação glicose líquor/soro muito baixa e proteína elevada favorece etiologia bacteriana.","INCORRETA. Micoses podem alterar líquor, mas o quadro agudo e o perfil não definem infecção fúngica."],"explanation":"O padrão integrado de pleocitose intensa, neutrófilos, relação glicose líquor/soro muito baixa e proteína elevada favorece etiologia bacteriana.","memorizar":"BACTERIANA: neutrófilos + proteína alta + glicose baixa, interpretados em conjunto.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"interpretação líquor bacteriano","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"difícil"},{"id":"ouro-rigor5-sc-A4-06","topicId":"sc-A4","stem":"Adolescente de 14 anos apresenta cefaleia, febre e fotofobia, mas está alerta e sem sinais de sepse. Líquor com 150 leucócitos/mm³, 82% linfócitos, glicose 64 mg/dL (sérica 96), proteína discretamente elevada, bacterioscopia negativa e PCR para enterovírus positiva. Qual leitura do conjunto é mais consistente?","options":["A pleocitose obriga diagnóstico bacteriano, independentemente de glicose e PCR.","Meningite viral por enterovírus, apoiada pelo PCR e perfil do líquor.","A glicose normal afasta qualquer meningite e transforma o líquor em normal.","A bacterioscopia negativa prova que não existe bactéria em nenhuma circunstância.","A proteína elevada, ainda que discretamente, define tuberculose meníngea."],"answer":1,"analysis":["INCORRETA. Pleocitose não diferencia sozinha agentes virais e bacterianos.","CORRETA. PCR molecular específica e bioquímica compatível favorecem etiologia viral; a interpretação sempre leva em conta gravidade e contexto.","INCORRETA. Pleocitose e PCR positiva indicam infecção do SNC.","INCORRETA. Sensibilidade do Gram depende da carga bacteriana e de antibiótico prévio.","INCORRETA. Proteína isolada não caracteriza etiologia tuberculosa."],"explanation":"PCR molecular específica e bioquímica compatível favorecem etiologia viral; a interpretação sempre leva em conta gravidade e contexto.","memorizar":"LÍQUOR VIRAL TÍPICO: pleocitose linfocitária, glicose geralmente preservada, PCR contextualizada.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"interpretação líquor viral","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"difícil"},{"id":"ouro-rigor5-sc-A4-07","topicId":"sc-A4","stem":"Menino de 3 anos recebeu cefalosporina intravenosa no hospital de origem por suspeita bacteriana. O líquor colhido horas depois tem cultura negativa, 1.100 células/mm³, predomínio neutrofílico, glicose muito baixa e proteína elevada. Qual interpretação evita um erro de descarte?","options":["Cultura negativa descarta meningite bacteriana mesmo após antibiótico.","Toda cultura negativa com neutrofilia confirma meningite viral.","A positividade do Gram é requisito obrigatório para iniciar tratamento.","A composição do líquor não deve ser interpretada após qualquer dose antibiótica.","Antibiótico prévio reduz rendimento cultural, sem excluir doença bacteriana."],"answer":4,"analysis":["INCORRETA. Tratamento prévio reduz sensibilidade microbiológica.","INCORRETA. Neutrofilia, hipoglicorraquia e proteína elevada sugerem processo bacteriano.","INCORRETA. Conduta empírica depende de suspeita e gravidade, não apenas do Gram.","INCORRETA. É possível integrar os dados, reconhecendo suas limitações.","CORRETA. A cultura do líquor pode se negativar após antibióticos. Perfil bioquímico, hemoculturas, testes moleculares e evolução ainda orientam diagnóstico."],"explanation":"A cultura do líquor pode se negativar após antibióticos. Perfil bioquímico, hemoculturas, testes moleculares e evolução ainda orientam diagnóstico.","memorizar":"ANTIBIÓTICO ANTES DO LÍQUOR pode esterilizar a cultura; não transforma bacteriana em viral.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"antibiótico antes da punção","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A4-08","topicId":"sc-A4","stem":"Lactente de 2 meses chega com febre e gemência. Punção realizada precocemente mostrou poucas células e bacterioscopia negativa. Horas depois evolui com piora clínica e hemocultura identifica pneumococo. Qual conclusão é mais segura?","options":["Líquor precoce pouco alterado não exclui meningite em progressão.","Líquor quase normal exclui meningite em todas as fases da infecção.","Pneumococo no sangue só produz pneumonia e não altera suspeita de doença do SNC.","O isolamento sanguíneo determina obrigatoriamente punção imediata mesmo se o paciente piorar hemodinamicamente.","A bacterioscopia negativa comprova ausência de infecção bacteriana do SNC."],"answer":0,"analysis":["CORRETA. No início do processo, o padrão liquórico pode ainda não ser clássico; bacteremia por patógeno meníngeo exige reavaliação clínica especializada.","INCORRETA. Inflamação liquórica pode ser discreta inicialmente.","INCORRETA. Pneumococo é patógeno relevante em meningite invasiva.","INCORRETA. A segurança do procedimento deve ser reavaliada.","INCORRETA. Sensibilidade do Gram não é absoluta."],"explanation":"No início do processo, o padrão liquórico pode ainda não ser clássico; bacteremia por patógeno meníngeo exige reavaliação clínica especializada.","memorizar":"LÍQUOR PRECOCE não é teste de exclusão absoluto em paciente com bacteremia e deterioração.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"líquor precoce e evolução","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A4-09","topicId":"sc-A4","stem":"Criança de 5 anos com febre e cefaleia inicia crise tônico-clônica generalizada que persiste há 7 minutos ao chegar ao pronto atendimento. Há hipótese de meningoencefalite. Qual é a prioridade antes da punção?","options":["Realizar punção durante a crise para evitar alteração posterior do líquor.","Aguardar cessação espontânea porque febre explica qualquer convulsão pediátrica.","Controlar crise e estabilizar ABCDE antes de avaliar punção.","Solicitar apenas eletroencefalograma antes de qualquer intervenção farmacológica.","Proibir antimicrobianos até a criança recuperar plenamente a consciência."],"answer":2,"analysis":["INCORRETA. O risco imediato é a crise ativa e a estabilização.","INCORRETA. Crise prolongada exige tratamento; nem toda convulsão febril é simples.","CORRETA. Crise prolongada é emergência neurológica; punção durante instabilidade/atividade convulsiva não é a primeira etapa.","INCORRETA. EEG não substitui controle de crise clínica prolongada.","INCORRETA. Infecção grave suspeita exige decisão terapêutica sem atraso desnecessário."],"explanation":"Crise prolongada é emergência neurológica; punção durante instabilidade/atividade convulsiva não é a primeira etapa.","memorizar":"CRISE PROLONGADA: estabilizar e controlar a convulsão antes de pensar em punção.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"convulsão ativa e estabilização","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"difícil"},{"id":"ouro-rigor5-sc-A4-10","topicId":"sc-A4","stem":"Adolescente de 15 anos com febre e cefaleia apresenta mudanças de comportamento, desorientação, crise focal e ressonância com anormalidade temporal. O líquor tem pleocitose linfocitária. Qual decisão etiológica deve ser considerada urgentemente além da cobertura bacteriana apropriada?","options":["Concluir que pleocitose linfocitária exclui encefalite herpética.","Atribuir o déficit cognitivo a estresse e realizar alta após antitérmico.","Tratar como meningite viral banal sem considerar envolvimento encefálico.","Suspeitar de encefalite herpética e iniciar terapia empírica indicada.","Esperar o PCR do líquor ficar positivo antes de qualquer antiviral em paciente grave."],"answer":3,"analysis":["INCORRETA. Líquor linfocitário é compatível com HSV.","INCORRETA. Alteração neurológica focal é sinal de gravidade.","INCORRETA. Disfunção cerebral e foco temporal exigem diferencial de encefalite.","CORRETA. Alteração de comportamento, crises focais e acometimento temporal são achados sugestivos de encefalite herpética, em que demora antiviral pode ser deletéria.","INCORRETA. A confirmação não deve atrasar terapia quando suspeita é relevante."],"explanation":"Alteração de comportamento, crises focais e acometimento temporal são achados sugestivos de encefalite herpética, em que demora antiviral pode ser deletéria.","memorizar":"FEBRE + ENCEFALOPATIA + CRISE FOCAL/TEMPORAL: considerar HSV e tratamento precoce.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"encefalite herpética","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A4-11","topicId":"sc-A4","stem":"Menino de 9 anos com otite média recente evolui com febre alta, cefaleia progressiva, vômitos e dor mastoidea. Desenvolve paralisia de VI nervo craniano. Qual interpretação explica a necessidade de investigação além de meningite simples?","options":["Investigar complicação intracraniana do foco otológico e déficit focal.","A paralisia do VI par é esperada e benigna em otite não complicada.","A melhora com analgésico exclui extensão da infecção.","O histórico de otite obriga diagnóstico de meningite viral sem investigação.","Punção imediata é sempre o primeiro passo independentemente do déficit neurológico."],"answer":0,"analysis":["CORRETA. Otite/mastoidite pode complicar com infecções intracranianas; neuropatia craniana nova não deve ser tratada como achado inespecífico.","INCORRETA. Déficit craniano sugere possível complicação intracraniana.","INCORRETA. Alívio sintomático não descarta processo intracraniano.","INCORRETA. Foco contíguo pode ser bacteriano e complicado.","INCORRETA. Déficit focal impõe reavaliar segurança da punção e imagem."],"explanation":"Otite/mastoidite pode complicar com infecções intracranianas; neuropatia craniana nova não deve ser tratada como achado inespecífico.","memorizar":"FOCO OTOLÓGICO + SINAL FOCAL: pesquisar complicação intracraniana.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"foco otogênico e complicações","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A4-12","topicId":"sc-A4","stem":"Criança de 10 anos com suspeita de meningococcemia apresenta plaquetas 29.000/mm³, INR elevado, sangramento em locais de punção e hipotensão. Qual aspecto limita mais fortemente a punção lombar nesta etapa?","options":["O achado de petéquias torna a punção obrigatória para estadiar a gravidade.","INR elevado só interfere na cultura, sem influência sobre segurança da punção.","A hipotensão torna a coleta mais informativa e deve ser ignorada.","Adiar punção por coagulopatia grave e instabilidade.","O procedimento é seguro desde que seja usada agulha fina, sem correção de distúrbios."],"answer":3,"analysis":["INCORRETA. Petéquias com coagulopatia elevam preocupação com sangramento, não justificam LP imediata.","INCORRETA. Distúrbio de coagulação eleva risco hemorrágico.","INCORRETA. Instabilidade exige ressuscitação.","CORRETA. Risco hemorrágico e instabilidade são contraindicações relevantes à punção no momento agudo.","INCORRETA. Calibre não resolve risco de coagulopatia grave."],"explanation":"Risco hemorrágico e instabilidade são contraindicações relevantes à punção no momento agudo.","memorizar":"COAGULOPATIA + INSTABILIDADE: tratar primeiro, puncionar somente quando seguro.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"coagulopatia como impedimento","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"difícil"},{"id":"ouro-rigor5-sc-A4-13","topicId":"sc-A4","stem":"Lactente de 7 meses, anteriormente hígido, tem febre persistente, choro inconsolável ao colo, vômitos e episódios de menor contato ocular. Ao exame, fontanela abaulada em repouso e redução da interação. Qual interpretação é mais adequada?","options":["A ausência de rigidez exclui meningite em menores de um ano.","Investigar acometimento do SNC e sinais de pressão intracraniana elevada.","Fontanela abaulada em repouso é achado esperado em lactente febril sem importância clínica.","O vômito isolado determina meningite, independentemente dos demais sinais.","A normalidade da ausculta respiratória permite descartar toda infecção invasiva."],"answer":1,"analysis":["INCORRETA. Sinais clássicos frequentemente estão ausentes em lactentes.","CORRETA. Abaulamento persistente com alterações de comportamento e febre aumenta suspeita de acometimento intracraniano; a segurança de LP precisa ser avaliada.","INCORRETA. Persistência em repouso, associada a alteração neurológica, é sinal preocupante.","INCORRETA. Vômito é inespecífico; é a combinação clínica que importa.","INCORRETA. Ausculta pulmonar normal não exclui doença do SNC."],"explanation":"Abaulamento persistente com alterações de comportamento e febre aumenta suspeita de acometimento intracraniano; a segurança de LP precisa ser avaliada.","memorizar":"FONTANELA ABAULADA EM REPOUSO + FEBRE + ALTERAÇÃO DO CONTATO: alerta neurológico.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"achados em menor de um ano","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"difícil"},{"id":"ouro-rigor5-sc-A4-14","topicId":"sc-A4","stem":"Menino de 11 anos com febre, cefaleia e bom estado geral tem líquor colhido nas primeiras horas: 140 células/mm³, 65% neutrófilos, glicose normal, proteína levemente elevada e PCR enteroviral positiva. Sem sinais de sepse, há evolução clínica favorável. Qual dado impede interpretar neutrofilia isolada como prova de bactéria?","options":["Neutrófilos acima de 50% no líquor definem meningite bacteriana sem exceções.","PCR enteroviral positiva é irrelevante quando há mais de 100 células.","Glicose normal exclui qualquer meningite.","Melhora clínica é critério para ignorar exame alterado sem seguimento.","Meningite enteroviral precoce pode apresentar neutrofilia liquórica."],"answer":4,"analysis":["INCORRETA. Viroses precoces podem iniciar com predomínio neutrofílico.","INCORRETA. Teste molecular específico tem valor diagnóstico contextual.","INCORRETA. Pleocitose e teste positivo apontam inflamação do SNC.","INCORRETA. Evolução ajuda, mas não apaga a necessidade de interpretação clínica.","CORRETA. O diferencial celular do líquor varia com fase; a combinação de PCR, glicose e evolução é mais informativa que uma porcentagem única."],"explanation":"O diferencial celular do líquor varia com fase; a combinação de PCR, glicose e evolução é mais informativa que uma porcentagem única.","memorizar":"NEUTROFILIA INICIAL não é sinônimo obrigatório de bactéria: interpretar todo o líquor.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"neutrófilos em meningite viral inicial","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A4-15","topicId":"sc-A4","stem":"Menino de 4 anos apresenta três semanas de febre baixa, perda ponderal, cefaleia e piora progressiva da marcha. Há contato domiciliar com adulto em tratamento de tuberculose pulmonar. O líquor tem 180 células/mm³, predomínio linfocitário, proteína de 240 mg/dL e glicose de 22 mg/dL. Qual hipótese deve subir na lista de prioridades?","options":["Meningite enteroviral não complicada, por toda pleocitose linfocitária com febre.","Meningite bacteriana piogênica aguda estabelecida, pois a glicose está baixa.","Meningite tuberculosa é hipótese importante neste contexto.","Síndrome pós-viral sem infecção ativa, porque a evolução excede sete dias.","Cefaleia tensional infantil, pois não há relato de rigidez nucal."],"answer":2,"analysis":["INCORRETA. A hipoglicorraquia acentuada, proteínas altas e curso de semanas não são padrão viral benigno típico.","INCORRETA. Glicose baixa não é exclusiva de bactéria piogênica e o contexto favorece tuberculose.","CORRETA. O curso arrastado e a exposição à tuberculose, associados ao líquor linfocitário de baixa glicose, são sinais de alerta para tuberculose meníngea, que exige avaliação e tratamento especializado urgentes.","INCORRETA. Persistência e piora neurológica são incompatíveis com alta sem investigação.","INCORRETA. Evolução sistêmica, alteração de marcha e líquor patológico não são explicadas por cefaleia primária."],"explanation":"O curso arrastado e a exposição à tuberculose, associados ao líquor linfocitário de baixa glicose, são sinais de alerta para tuberculose meníngea, que exige avaliação e tratamento especializado urgentes.","memorizar":"CURSO SUBAGUDO + CONTATO TB + LÍQUOR LINFOCITÁRIO COM GLICOSE BAIXA: pensar em TB meníngea.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"síndrome tuberculosa subaguda","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A4-16","topicId":"sc-A4","stem":"Menina de 10 anos tem glicose liquórica de 45 mg/dL e glicemia sérica próxima da punção de 180 mg/dL. Outro atendimento interpretou a glicose liquórica como absolutamente normal por estar acima de 40 mg/dL. Qual ajuste é essencial?","options":["Usar apenas o valor sérico, porque a glicose do líquor não participa da análise etiológica.","Concluir que a hiperglicemia descarta meningite bacteriana.","Assumir relação de 4,0 porque se divide glicemia pelo valor do líquor e chamá-la normal.","Repetir punção obrigatoriamente sem integrar dados clínicos e outras medidas do líquor.","Interpretar relação glicose líquor/soro de aproximadamente 0,25."],"answer":4,"analysis":["INCORRETA. A relação líquor/soro é importante para interpretar hipoglicorraquia.","INCORRETA. Glicemia elevada não exclui infecção do SNC e exige comparação relativa.","INCORRETA. A comparação convencional é glicose liquórica dividida pela sérica.","INCORRETA. A decisão depende do quadro e segurança, e a relação já oferece informação.","CORRETA. A glicose liquórica depende do nível sérico; isoladamente 45 mg/dL pode parecer pouco alterada, mas a relação de 0,25 indica hipoglicorraquia relativa relevante."],"explanation":"A glicose liquórica depende do nível sérico; isoladamente 45 mg/dL pode parecer pouco alterada, mas a relação de 0,25 indica hipoglicorraquia relativa relevante.","memorizar":"GLICOSE DO LÍQUOR deve ser contextualizada com glicemia sérica.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"pareamento da glicose líquor-soro","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A4-17","topicId":"sc-A4","stem":"Adolescente de 16 anos apresenta febre e cefaleia, mas a principal alteração é confusão persistente, desorientação temporal, alucinações visuais e crise focal. Mantém discreto desconforto cervical. Qual enquadramento é mais importante para direcionar a investigação?","options":["Classificar meningite viral simples, pois confusão é sinal específico de meninge inflamada.","Diagnosticar episódio psiquiátrico primário sem investigação por haver alucinações.","Suspeitar de encefalite ou meningoencefalite, não apenas meningite.","Afastar infecção do SNC porque rigidez cervical não é intensa.","Presumir intoxicação isolada sem avaliar infecção, porque alucinações são comuns na adolescência."],"answer":2,"analysis":["INCORRETA. Confusão importante é sinal de envolvimento encefálico.","INCORRETA. Febre e crises focais requerem excluir causa orgânica.","CORRETA. A disfunção encefálica aguda e crises focais elevam a suspeita de encefalite, em que testes e condutas podem diferir de meningite isolada.","INCORRETA. Sinais meníngeos não precisam ser proeminentes em encefalite.","INCORRETA. Encefalopatia febril exige investigação de infecção e outras etiologias."],"explanation":"A disfunção encefálica aguda e crises focais elevam a suspeita de encefalite, em que testes e condutas podem diferir de meningite isolada.","memorizar":"ALTERAÇÃO DE CONSCIÊNCIA/COGNIÇÃO + FEBRE: considerar ENCEFALITE, não apenas meningite.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"diferencial meníngeo versus encefálico","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"difícil"},{"id":"ouro-rigor5-sc-A4-18","topicId":"sc-A4","stem":"Recém-nascido de 12 dias apresenta hipotermia, sucção fraca, instabilidade respiratória e letargia. O obstetra informa colonização materna por estreptococo do grupo B. Qual conclusão microbiológica é a mais apropriada?","options":["Investigar sepse/meningite neonatal, incluindo estreptococo do grupo B.","Desconsiderar estreptococo do grupo B porque só causa doença nas primeiras 24 horas de vida.","Excluir infecção porque a temperatura está baixa, não elevada.","Esperar sinais de Kernig/Brudzinski antes de investigar meningite.","Pressupor que o quadro é fisiológico porque recém-nascidos costumam ter sucção variável."],"answer":0,"analysis":["CORRETA. Sepse e meningite neonatais podem se manifestar com sinais inespecíficos e hipotermia; estreptococo do grupo B integra as etiologias relevantes nessa faixa etária.","INCORRETA. Pode haver doença invasiva de início tardio.","INCORRETA. Hipotermia também pode ser manifestação de infecção neonatal.","INCORRETA. Sinais meníngeos clássicos não são critérios confiáveis nessa idade.","INCORRETA. Letargia e dificuldade respiratória com instabilidade térmica são sinais de alarme."],"explanation":"Sepse e meningite neonatais podem se manifestar com sinais inespecíficos e hipotermia; estreptococo do grupo B integra as etiologias relevantes nessa faixa etária.","memorizar":"NEONATO: INFECÇÃO pode manifestar hipotermia, recusa alimentar e letargia.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"patógenos no período neonatal","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"difícil"},{"id":"ouro-rigor5-sc-A4-19","topicId":"sc-A4","stem":"Menino de 12 anos em imunossupressão intensa apresenta três semanas de cefaleia progressiva, diplopia e vômitos. Punção realizada após avaliação de segurança demonstra pressão de abertura elevada, pleocitose linfocitária discreta e proteína aumentada. Qual hipótese adicional é particularmente relevante?","options":["Afastar infecção porque a pleocitose não é intensa.","Assumir cefaleia psicogênica porque o início foi gradual.","Confirmar meningite bacteriana piogênica apenas porque a proteína está elevada.","Investigar meningite oportunista fúngica, incluindo criptococose.","Descartar hipertensão intracraniana porque não há informação de fontanela."],"answer":3,"analysis":["INCORRETA. Em imunossuprimidos, resposta celular pode ser pouco expressiva.","INCORRETA. Diplopia, vômitos e pressão de abertura aumentada indicam doença orgânica.","INCORRETA. Proteína elevada é inespecífica; curso e imunidade alteram hipóteses.","CORRETA. Imunossupressão e cefaleia subaguda com hipertensão liquórica requerem investigação de agentes oportunistas, não apenas enterovírus.","INCORRETA. Fontanela não é parâmetro aplicável a essa faixa etária."],"explanation":"Imunossupressão e cefaleia subaguda com hipertensão liquórica requerem investigação de agentes oportunistas, não apenas enterovírus.","memorizar":"IMUNOSSUPRESSÃO + LCR SUBAGUDO + PRESSÃO ALTA: investigar infecção oportunista.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"imunossupressão e diferencial fúngico","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A4-20","topicId":"sc-A4","stem":"Uma criança de 9 anos recebe diagnóstico confirmado de doença meningocócica invasiva. A irmã de 6 anos compartilhou o quarto e contato direto de saliva nas últimas 48 horas e permanece assintomática. Qual medida preventiva precisa ser avaliada para a irmã?","options":["Vacinação futura, sem qualquer avaliação imediata, substitui todas as medidas para contatos.","Avaliar quimioprofilaxia da irmã como contato próximo.","Punção lombar em todos os contatos assintomáticos antes de qualquer conduta.","Aguardar febre para então avaliar a necessidade de prevenção.","Antibiótico intravenoso prolongado para todo contato domiciliar assintomático."],"answer":1,"analysis":["INCORRETA. Imunização não substitui a decisão oportuna sobre quimioprofilaxia.","CORRETA. Contatos domiciliares próximos de caso meningocócico têm risco aumentado e são público-alvo da avaliação de quimioprofilaxia.","INCORRETA. Punção não é rastreamento rotineiro de contatos saudáveis.","INCORRETA. Prevenção é indicada conforme exposição, antes dos sintomas.","INCORRETA. Profilaxia de contatos é distinta do tratamento terapêutico de doença invasiva."],"explanation":"Contatos domiciliares próximos de caso meningocócico têm risco aumentado e são público-alvo da avaliação de quimioprofilaxia.","memorizar":"MENINGOCOCO CONFIRMADO: contato domiciliar próximo requer avaliação de QUIMIOPROFILAXIA.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"exposição domiciliar a meningococo","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"difícil"},{"id":"ouro-rigor5-sc-A4-21","topicId":"sc-A4","stem":"Adolescente de 15 anos é admitido com febre alta, púrpura e choque séptico com forte suspeita de doença meningocócica. A equipe debate quais medidas institucionais devem acompanhar o tratamento imediato. Qual orientação é a mais adequada?","options":["Instituir precauções por gotículas e medidas de saúde pública concomitantes.","Usar somente precauções de contato por pele, porque transmissão é exclusivamente por púrpura.","Evitar precauções até confirmação por cultura, para não prejudicar exames.","Deixar a profilaxia de contatos substituir o tratamento do caso index.","Fazer rastreamento familiar antes de iniciar ressuscitação do paciente em choque."],"answer":0,"analysis":["CORRETA. A transmissão por secreções respiratórias exige precauções e medidas de saúde pública, mas elas são concomitantes à estabilização do paciente.","INCORRETA. Meningococo é transmitido por secreções respiratórias.","INCORRETA. Suspeita clínica justifica medidas de proteção apropriadas.","INCORRETA. Medida para contatos não trata a pessoa com doença invasiva.","INCORRETA. A estabilidade hemodinâmica e o tratamento são prioritários e urgentes."],"explanation":"A transmissão por secreções respiratórias exige precauções e medidas de saúde pública, mas elas são concomitantes à estabilização do paciente.","memorizar":"DOENÇA MENINGOCÓCICA: GOTÍCULAS + tratamento imediato + saúde pública.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"isolamento em suspeita meningocócica","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"difícil"},{"id":"ouro-rigor5-sc-A4-22","topicId":"sc-A4","stem":"Menino de 5 anos recebe alta após meningite bacteriana tratada, sem déficit motor aparente. Três semanas depois, os pais relatam que ele pede repetição constante das palavras e aumenta o volume da televisão. Qual seguimento foi negligenciado se não foi programado?","options":["Acompanhamento exclusivamente ortopédico porque toda sequela pós-meningite é motora.","Não investigar audição porque o exame motor na alta era normal.","Atribuir dificuldade de compreensão a desatenção sem testar audição.","Indicar tratamento anti-infeccioso empírico prolongado sem avaliar a queixa.","Programar avaliação audiológica após meningite bacteriana."],"answer":4,"analysis":["INCORRETA. Comprometimento auditivo é sequela importante.","INCORRETA. Funções motoras e auditivas são independentes.","INCORRETA. Alterações auditivas precisam ser descartadas objetivamente.","INCORRETA. A queixa tardia sugere avaliação de sequela, não demonstra recidiva ativa.","CORRETA. A inflamação na orelha interna e vias auditivas pode causar hipoacusia pós-meningite; avaliação precoce ajuda reabilitação."],"explanation":"A inflamação na orelha interna e vias auditivas pode causar hipoacusia pós-meningite; avaliação precoce ajuda reabilitação.","memorizar":"PÓS-MENINGITE BACTERIANA: pensar em AVALIAÇÃO AUDITIVA.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"sequela auditiva e seguimento","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"difícil"},{"id":"ouro-rigor5-sc-A4-23","topicId":"sc-A4","stem":"Menina de 2 anos tem febre e episódio convulsivo com desvio ocular persistente à esquerda, duração de 18 minutos e recuperação da consciência lenta. Depois, mantém irritabilidade intensa. Qual raciocínio impede classificar o episódio como convulsão febril simples sem investigação?","options":["Toda crise em idade de 6 meses a 5 anos acompanhada de febre é simples, sem exceção.","O desvio ocular não tem valor clínico se houve febre no mesmo dia.","Classificar como febril complexa e investigar sinais persistentes do SNC.","A duração de 18 minutos é sempre compatível com convulsão febril simples.","A irritabilidade persistente confirma recuperação normal e impede considerar meningite."],"answer":2,"analysis":["INCORRETA. Critérios de duração, focalidade e recorrência importam.","INCORRETA. Focalidade é um dos critérios que tornam a crise complexa.","CORRETA. Crise febril simples exige convulsão generalizada breve e recuperação típica; os dados apresentados modificam risco e necessidade de avaliação.","INCORRETA. Duração prolongada contraria a definição usual de simples.","INCORRETA. Estado neurológico atípico deve ser valorizado."],"explanation":"Crise febril simples exige convulsão generalizada breve e recuperação típica; os dados apresentados modificam risco e necessidade de avaliação.","memorizar":"FEBRIL COMPLEXA + EXAME NEUROLÓGICO ATÍPICO: excluir causa intracraniana relevante.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"diferenciar crise febril simples e infecção SNC","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A4-24","topicId":"sc-A4","stem":"Criança de 4 anos com suspeita muito forte de meningite bacteriana é submetida a coleta segura de culturas, e a antibioticoterapia intravenosa está prestes a iniciar. Discute-se corticoide adjuvante conforme agente e recomendação local. Qual princípio temporal evita perder seu possível benefício?","options":["Dexametasona é obrigatória para toda meningite viral, independentemente de agente.","A primeira dose deve ocorrer preferencialmente dias depois do antibiótico, quando a inflamação terminou.","O corticoide substitui antibióticos enquanto se aguarda cultura.","Quando indicada, oferecer dexametasona antes ou junto do antibiótico inicial.","Um único protocolo é válido para qualquer idade, agente e epidemiologia."],"answer":3,"analysis":["INCORRETA. Corticoide adjuvante não é rotina para viroses benignas.","INCORRETA. A janela de benefício, quando existe, está vinculada ao início da terapia antibacteriana.","INCORRETA. Adjuvante não é antimicrobiano.","CORRETA. O objetivo do adjuvante é modular resposta inflamatória associada à lise bacteriana inicial; uso tardio tem menor plausibilidade de benefício.","INCORRETA. Indicação depende de faixa etária e referencial vigente."],"explanation":"O objetivo do adjuvante é modular resposta inflamatória associada à lise bacteriana inicial; uso tardio tem menor plausibilidade de benefício.","memorizar":"DEXAMETASONA, SE INDICADA: antes ou junto ao PRIMEIRO ANTIBIÓTICO.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"meningite e dexametasona","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A4-25","topicId":"sc-A4","stem":"O laboratório notifica que o líquor de um escolar com meningite purulenta contém diplococos gram-negativos. Há preocupação com transmissão escolar. Qual hipótese etiológica e medida associada são mais coerentes?","options":["Streptococcus pneumoniae, porque o pneumococo é diplococo gram-negativo.","Neisseria meningitidis; avaliar gotículas e contatos próximos.","Listeria monocytogenes, porque o agente aparece como diplococo gram-negativo.","Enterovírus, porque infecções virais se coram no Gram com morfologia bacteriana.","Haemophilus influenzae, porque todo bacilo gram-negativo assume morfologia de diplococo."],"answer":1,"analysis":["INCORRETA. Pneumococo é gram-positivo.","CORRETA. Diplococos gram-negativos em líquor são pista microbiológica clássica de meningococo, que demanda medidas assistenciais e de saúde pública.","INCORRETA. Listeria é bacilo gram-positivo.","INCORRETA. Vírus não são identificados como diplococos no Gram.","INCORRETA. Haemophilus é cocobacilo gram-negativo, com morfologia distinta."],"explanation":"Diplococos gram-negativos em líquor são pista microbiológica clássica de meningococo, que demanda medidas assistenciais e de saúde pública.","memorizar":"DIPLOCOCOS GRAM-NEGATIVOS no líquor: meningococo é hipótese-chave.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"bacterioscopia Gram","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"difícil"},{"id":"ouro-rigor5-sc-A4-26","topicId":"sc-A4","stem":"Menina de 11 anos com sinusite complicada tem cefaleia progressiva, febre e crises focais recorrentes. A RM revela lesão expansiva com realce periférico e edema perilesional. Qual conduta diagnóstica deve evitar uma punção precipitada?","options":["Fazer punção imediata pois qualquer febre com cefaleia é meningite sem lesão expansiva.","Concluir meningite viral autolimitada apesar do achado expansivo.","Suspeitar de abscesso cerebral e evitar punção sem avaliar risco.","Repetir apenas teste de antígeno estreptocócico faríngeo e dispensar a RM.","Aguardar regressão espontânea das crises e do edema sem atendimento."],"answer":2,"analysis":["INCORRETA. Imagem mostra lesão com efeito de massa potencial.","INCORRETA. O padrão de imagem exige outra hipótese grave.","CORRETA. A lesão expansiva com edema e crises focais orienta foco parenquimatoso; punção pode ser perigosa e não é meio primário de diagnosticar abscesso.","INCORRETA. O achado intracraniano já requer abordagem especializada.","INCORRETA. Abscesso cerebral pode piorar rapidamente e requer cuidado urgente."],"explanation":"A lesão expansiva com edema e crises focais orienta foco parenquimatoso; punção pode ser perigosa e não é meio primário de diagnosticar abscesso.","memorizar":"SINUSITE + SINAL FOCAL + LESÃO COM REALCE EM ANEL: pensar em ABSCESSO, cautela com LP.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"diferencial abscesso cerebral","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A4-27","topicId":"sc-A4","stem":"Lactente de 2 meses tem punção lombar traumática com numerosas hemácias e discreta elevação de leucócitos. Está febril, com irritabilidade e antecedente de antibioticoterapia prévia. Qual interpretação evita falsa segurança?","options":["Interpretar punção traumática com cautela, sem excluir meningite apenas por correção celular.","Subtrair automaticamente um número fixo de leucócitos e dar alta se o resultado corrigido for baixo.","Considerar toda hemácia no líquor como prova de meningite bacteriana.","Ignorar antibiótico prévio porque ele não modifica culturas.","Usar ausência de rigidez nucal como critério suficiente para afastar infecção."],"answer":0,"analysis":["CORRETA. Hemácias provenientes de sangue periférico podem distorcer contagens, mas correções matemáticas isoladas não substituem julgamento clínico em lactente com risco de doença invasiva.","INCORRETA. Correções isoladas podem perder sensibilidade em cenário de risco.","INCORRETA. Punção traumática pode introduzir hemácias sem hemorragia intracraniana.","INCORRETA. Terapia anterior pode reduzir o rendimento microbiológico.","INCORRETA. Lactentes podem não apresentar sinais meníngeos clássicos."],"explanation":"Hemácias provenientes de sangue periférico podem distorcer contagens, mas correções matemáticas isoladas não substituem julgamento clínico em lactente com risco de doença invasiva.","memorizar":"LP TRAUMÁTICA: NÃO usar correção celular isolada como exclusão de meningite.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"punção traumática e interpretação","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A4-28","topicId":"sc-A4","stem":"Menino de 8 anos com febre e cefaleia desenvolve bradicardia relativa, hipertensão arterial e respiração irregular, associadas a rebaixamento progressivo de consciência. O residente planeja punção para esclarecimento etiológico. Qual risco prioritário muda o plano?","options":["A tríade define recuperação hemodinâmica e indica punção imediata.","Bradicardia isolada prova ausência de risco neurológico por não haver taquicardia.","Solicitar hemograma e aguardar dias antes de qualquer intervenção.","Interpretar como resposta normal à febre e continuar investigação ambulatorial.","Suspeitar de hipertensão intracraniana grave e adiar punção."],"answer":4,"analysis":["INCORRETA. O padrão é preocupante para hipertensão intracraniana, não estabilização.","INCORRETA. Conjunto com hipertensão e ventilação irregular é altamente alarmante.","INCORRETA. Há deterioração neurológica aguda.","INCORRETA. Febre não explica com segurança a tríade e rebaixamento.","CORRETA. Sinais de resposta de Cushing associados à alteração de consciência são emergências neurológicas e exigem mudança da sequência de investigação."],"explanation":"Sinais de resposta de Cushing associados à alteração de consciência são emergências neurológicas e exigem mudança da sequência de investigação.","memorizar":"CUSHING + REBAIXAMENTO: HIC grave; NÃO priorizar LP.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"sinal de hipertensão intracraniana","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"muito difícil"},{"id":"ouro-rigor5-sc-A4-29","topicId":"sc-A4","stem":"Criança de 3 anos em tratamento para meningite bacteriana evolui com aumento progressivo do perímetro cefálico para a idade, vômitos em jato, irritabilidade e alterações de equilíbrio. Qual complicação deve ser considerada?","options":["Reação alérgica cutânea exclusiva ao antibiótico, mesmo sem lesões cutâneas.","Investigar hidrocefalia como complicação da meningite.","Alta imediata porque hidrocefalia não ocorre após meningite.","Perda auditiva como explicação suficiente para vômitos em jato e sinais de HIC.","Atribuir todo quadro a intolerância alimentar sem reavaliar neurologicamente."],"answer":1,"analysis":["INCORRETA. Os sintomas neurológicos progressivos pedem avaliação intracraniana.","CORRETA. Inflamação nas vias liquóricas pode prejudicar circulação/reabsorção e produzir sinais de hipertensão intracraniana e hidrocefalia.","INCORRETA. Hidrocefalia é complicação conhecida de meningite.","INCORRETA. Hipoacusia não explica hipertensão intracraniana.","INCORRETA. A evolução e contexto aumentam suspeita de complicação do SNC."],"explanation":"Inflamação nas vias liquóricas pode prejudicar circulação/reabsorção e produzir sinais de hipertensão intracraniana e hidrocefalia.","memorizar":"PIORA NEUROLÓGICA APÓS MENINGITE: considerar HIDROCEFALIA/complicação intracraniana.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"evolução com hidrocefalia","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"difícil"},{"id":"ouro-rigor5-sc-A4-30","topicId":"sc-A4","stem":"Menino de 6 anos com pneumonia bacteriana recente desenvolve febre alta, rigidez nucal e alteração de consciência. No Gram do líquor há diplococos gram-positivos. Qual agente se torna mais provável?","options":["Neisseria meningitidis, que apresenta diplococos gram-positivos típicos.","Listeria monocytogenes, identificada principalmente por diplococos gram-positivos.","Enterovírus, cujo capsídeo aparece como diplococo no Gram.","Streptococcus pneumoniae, diplococo gram-positivo.","Escherichia coli, tipicamente diplococo gram-positivo."],"answer":3,"analysis":["INCORRETA. Meningococo é diplococo gram-negativo.","INCORRETA. Listeria é bacilo gram-positivo.","INCORRETA. Vírus não são corados como diplococos.","CORRETA. Morfologia gram-positiva em diplococos e foco respiratório favorecem pneumococo.","INCORRETA. E. coli é bacilo gram-negativo."],"explanation":"Morfologia gram-positiva em diplococos e foco respiratório favorecem pneumococo.","memorizar":"DIPLOCOCOS GRAM-POSITIVOS + infecção invasiva: PNEUMOCOCO é hipótese-chave.","source":"Trilha de Ouro, biblioteca clínica SDCII A4 Meningite; elaboração autoral de revisão; sem validação externa de diretriz em tempo real.","skill":"questoes-da-apostila-de-ouro","type":"objective","topic":"Meningite","group":"P2 • Saúde da Criança II","competence":"meningite e patógeno pneumocócico","kind":"case","reviewStatus":"revisão editorial local de coerência e estrutura; recomenda-se confrontar condutas com protocolo e fontes oficiais","degree":"difícil"}]};
